import{_ as a,o,c as t,a5 as c}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"Plan — G4 Media Package/Campaign: View + Approve (Mobile)","description":"","frontmatter":{},"headers":[],"relativePath":"mobile/features/g4-package-campaign/plan.md","filePath":"mobile/features/g4-package-campaign/plan.md"}'),i={name:"mobile/features/g4-package-campaign/plan.md"};function n(l,e,r,d,h,p){return o(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="plan-—-g4-media-package-campaign-view-approve-mobile" tabindex="-1">Plan — G4 Media Package/Campaign: View + Approve (Mobile) <a class="header-anchor" href="#plan-—-g4-media-package-campaign-view-approve-mobile" aria-label="Permalink to &quot;Plan — G4 Media Package/Campaign: View + Approve (Mobile)&quot;">​</a></h1><p>&gt; <a href="./spec.html">spec.md</a> — chi tiết API/flows/business rules đầy đủ. File này là bản tóm tắt thứ tự implement + quyết định kỹ thuật chốt.</p><h2 id="thu-tu-implement-theo-dependency" tabindex="-1">Thứ tự implement (theo dependency) <a class="header-anchor" href="#thu-tu-implement-theo-dependency" aria-label="Permalink to &quot;Thứ tự implement (theo dependency)&quot;">​</a></h2><ol><li><strong>Package screens trước</strong> (đơn giản hơn Campaign, không có optimistic lock phức tạp): <ul><li>Package List + Detail (<code>negotiationStatus</code>, <code>finalTerms</code>, <code>approvedBy*At</code>).</li><li>Nút Approve Package — <strong>chặn bởi <code>ApproveMediaPackageRequest</code> DTO chưa đọc field chi tiết</strong>, phải đọc trước khi code mutation.</li></ul></li><li><strong>Campaign screens:</strong><ul><li>Campaign List + Detail (Strategy/BrandGuideline/Timeline/Deliverables/WorkItems).</li><li>Nút Approve Campaign role-gated theo <code>approvedByAgencyAt</code>/<code>approvedByClientAt</code>.</li><li>Mutation approve với <code>expectedVersion=contentVersion</code> (optimistic lock).</li></ul></li><li><strong>Error handling:</strong><ul><li>409 <code>CAMPAIGN_VERSION_CONFLICT</code> → refetch, không tự động retry.</li><li>Invalidate cache sau approve thành công.</li></ul></li></ol><h2 id="quyet-đinh-ky-thuat-đa-chot" tabindex="-1">Quyết định kỹ thuật đã chốt <a class="header-anchor" href="#quyet-đinh-ky-thuat-đa-chot" aria-label="Permalink to &quot;Quyết định kỹ thuật đã chốt&quot;">​</a></h2><ul><li><strong>Dùng <code>WorkspaceCampaignController</code> (<code>/workspaces/{id}/campaigns/...</code>), KHÔNG dùng <code>MediaCampaignController</code> (<code>/media-campaigns/...</code>)</strong> — route thứ 2 có vẻ cũ/dự phòng, không được web gọi (xác nhận bằng cách đọc <code>campaignService.ts</code> của web).</li><li><strong>1 endpoint approve duy nhất cho cả 2 phía</strong> — server tự xác định AGENCY/CLIENT từ <code>CampaignWorkspaceAccess.side()</code>, mobile KHÔNG gửi cờ &quot;tôi là ai&quot; trong body, chỉ gửi <code>expectedVersion</code>.</li><li><strong><code>expectedVersion</code> dùng <code>contentVersion</code> (field nghiệp vụ), KHÔNG dùng <code>rowVersion</code></strong> (Hibernate <code>@Version</code> nội bộ) — đọc tại thời điểm bấm nút Approve, không cache stale.</li><li><strong>Approve KHÔNG tự động đẩy Task</strong> — đó là hành động &quot;deploy&quot; riêng (<code>POST .../deploy</code>), ngoài scope G4. Khác với mô tả BA &quot;approve → tự động đẩy backlog&quot; — theo code thật, 2 bước tách biệt.</li><li><strong>Server idempotent theo phía</strong> — double-tap approve không lỗi, trả lại campaign hiện tại. Mobile vẫn nên disable nút khi pending cho UX, không bắt buộc để tránh lỗi server.</li></ul><h2 id="viec-can-xac-nhan-truoc-khi-code-chua-lam-xem-spec-muc-8" tabindex="-1">Việc cần xác nhận trước khi code (chưa làm, xem spec mục 8) <a class="header-anchor" href="#viec-can-xac-nhan-truoc-khi-code-chua-lam-xem-spec-muc-8" aria-label="Permalink to &quot;Việc cần xác nhận trước khi code (chưa làm, xem spec mục 8)&quot;">​</a></h2><ul><li>2 controller Campaign trùng route — cần backend xác nhận route nào chính thức/sắp deprecate.</li><li><code>ApproveMediaPackageRequest</code> DTO — đọc field thật (có <code>expectedVersion</code> tương tự Campaign hay không) trước khi code approve Package.</li><li>BA mô tả &quot;approve tự đẩy backlog&quot; khác code — cần BA/PO xác nhận đây là chủ định (2 bước tách biệt do an toàn) hay doc chưa cập nhật.</li><li><code>PackageDeliverable</code>/<code>CampaignWorkItem</code>/<code>DeliverableAllocation</code> DTO con chưa đọc chi tiết — đọc trước khi thiết kế UI render từng field trong Campaign Detail.</li></ul><h2 id="rui-ro-con-mo" tabindex="-1">Rủi ro còn mở <a class="header-anchor" href="#rui-ro-con-mo" aria-label="Permalink to &quot;Rủi ro còn mở&quot;">​</a></h2><ul><li>Push notification khi phía kia approve — server có gọi <code>notifyOpposite(...)</code> nhưng G4 chưa cover tích hợp push mobile; để domain notification sau xử lý nếu cần real-time alert.</li></ul>',10)])])}const m=a(i,[["render",n]]);export{g as __pageData,m as default};
